BEGIN;
DO $guard$ BEGIN
IF (SELECT coalesce(max(version),0) FROM public.contract_master_versions WHERE active)=4 THEN NULL;
ELSE RAISE EXCEPTION 'Preflight: contrato mestre ativo alterado';END IF;
IF (SELECT count(*) FROM public.service_catalog WHERE active)<>38 THEN RAISE EXCEPTION 'Preflight: catálogo ativo divergiu';END IF;
