VALUES ('am','Projeto Hidráulico','complementar',true,'Projeto predial das instalações hidráulicas de água fria e, quando contratada, água quente, compreendendo distribuição, reservação e pontos de consumo para ambientes e unidades indicados no escopo. Esgoto não integra automaticamente esta atividade.','["Plantas hidráulicas das áreas contratadas","Detalhes e esquemas hidráulicos expressamente previstos","Dimensionamentos e indicações técnicas compatíveis com a etapa contratada"]'::jsonb,'["Projeto de esgoto sanitário e drenagem pluvial não contratados","Execução de instalações e ART de execução de obra","Vistorias e projetos de redes públicas não contratados"]'::jsonb,'["Projeto arquitetônico atualizado","Dados de abastecimento, reservação e equipamentos","Indicação dos ambientes e pontos atendidos"]'::jsonb,2,'["PDF"]'::jsonb,true,'Prazo conforme atividade, parâmetros e entregáveis efetivamente contratados.',ARRAY['1.1','1.2','1.4','5.5','5.6','10.2']::text[],1,true,5);
