VALUES ('an','Elaboração de Book de Vendas','visualizacao',true,'Planejamento gráfico e diagramação de material técnico-comercial de apresentação do empreendimento utilizando informações, plantas e imagens fornecidas ou expressamente contratadas e aprovadas.','["Composição e diagramação de páginas contratadas","Inserção de plantas, imagens e informações comerciais autorizadas","Book final em PDF conforme escopo"]'::jsonb,'["Renders, projetos ou modelos tridimensionais novos não contratados","Garantia de resultados comerciais ou vendas","Impressão, arquivo editável e uso de materiais sem licença não contratados"]'::jsonb,'["Textos, plantas, imagens e marca autorizados","Número de páginas, público e formato pretendido","Informações comerciais atualizadas e aprovadas"]'::jsonb,null,'["PDF"]'::jsonb,true,'Prazo conforme atividade, parâmetros e entregáveis efetivamente contratados.',ARRAY['1.1','1.2','1.4','5.5','5.6','10.2']::text[],1,true,5);
INSERT INTO public.service_catalog(code,name,category,level_applicable,description,deliverables,exclusions,client_inputs,default_revisions,delivery_formats,acceptance_required,planning_reference,contract_clause_refs,version,active,last_contract_master_version)
VALUES ('ao','Emissão e Regularização de ART','documentacao',true,'Providências de cadastramento, registro, complementação, substituição, regularização ou baixa de ART relativas exclusivamente a atividades técnicas legalmente assumidas por profissional habilitado, quando cabíveis segundo as normas do CREA. Não torna facultativa a ART obrigatória do serviço contratado.','["Conferência dos dados de responsabilidade técnica pertinentes","Cadastramento e registro de ART cabível","Comprovante de registro após recolhimento da taxa pelo cliente"]'::jsonb,'["ART de execução sem contratação e assunção efetiva da execução","Assunção de responsabilidade fictícia por serviços de terceiros","Taxas do CREA e documentos de terceiros não contratados"]'::jsonb,'["Dados de contratante, contrato e local","Atividades técnicas efetivamente contratadas","Antecipação ou reembolso comprovado da taxa de ART"]'::jsonb,null,'["PDF"]'::jsonb,true,'Prazo conforme atividade, parâmetros e entregáveis efetivamente contratados.',ARRAY['1.1','1.2','1.4','5.5','5.6','10.2']::text[],1,true,5);
INSERT INTO public.service_catalog_versions(service_code,version,snapshot,contract_master_version,created_by) SELECT code,version,to_jsonb(s),last_contract_master_version,null FROM public.service_catalog s WHERE code IN ('c','f','g','k','l','m','q','am','an','ao') ON CONFLICT(service_code,version) DO NOTHING;
INSERT INTO public.service_level_scope_versions(service_code,level_code,version,snapshot,created_by) SELECT service_code,level_code,version,to_jsonb(s),null FROM public.service_level_scope_catalog s WHERE service_code IN ('c','f','g','k','l','m','q','am','an','ao') ON CONFLICT(service_code,level_code,version) DO NOTHING;
WITH updates AS (SELECT * FROM jsonb_to_recordset('[{"code":"c","level":"bronze","budget":"Projeto Legal — nível BRONZE. Prestação essencial, limitada aos produtos e atividades expressamente discriminados na contratação. Objeto técnico: Preparação das peças técnicas necessárias ao protocolo ou análise perante o órgão competente, limitada ao escopo e à legislação aplicável ao processo contratado. Entregáveis de referência, sujeitos às quantidades e unidades expressamente contratadas: Peças gráficas exigíveis para o protocolo contratado; Quadros e informações urbanísticas pertinentes; Ajustes decorrentes de exigências do órgão, quando abrangidos pelo contrato; Organização documental técnica do processo. Exclusões específicas desta atividade: Taxas e emolumentos; Documentos de terceiros não previstos; Projetos complementares não contratados; Garantia de aprovação por órgão público. Nos serviços de aprovação e legalização, os documentos complementares, certidões, matrículas, procurações, levantamentos topográficos/planialtimétricos e demais peças não incluídas no projeto contratado são providenciados e pagos pelo CONTRATANTE, mesmo quando exigidos pela prefeitura. A CONTRATADA registra as ARTs legalmente exigíveis de seus projetos; todas as taxas de ART são custeadas pelo CONTRATANTE, por adiantamento ou reembolso comprovado. Correções de falhas técnicas próprias e peças integrantes do projeto contratado permanecem de responsabilidade da CONTRATADA. Não se incluem serviços de outra atividade por mera seleção de nível Bronze, Prata ou Ouro. Quantidades, prazos e marcos de aceite serão os registrados no orçamento e Anexo I, sem ampliação tácita do escopo.","contract":"A CONTRATADA prestará Projeto Legal no nível BRONZE, exclusivamente para o objeto, unidades, etapas, quantidades, visitas, revisões e formatos selecionados e aprovados. Prestação essencial, limitada aos produtos e atividades expressamente discriminados na contratação. Objeto técnico: Preparação das peças téc