INSERT INTO public.service_level_scope_catalog(service_code,level_code,applicable,budget_description,contract_scope,annex_scope,included_deliverables,excluded_deliverables,parameters,revisions_included,visits_included,detail_level,delivery_formats,inherit_legacy_catalog,review_status,source_service_version,source_level_version,version,active)
SELECT u.code,u.level,true,u.budget,u.contract,u.annex,s.deliverables,s.exclusions,coalesce(u.params,'[]'::jsonb),s.default_revisions,null,CASE u.level WHEN 'bronze' THEN 'essencial' WHEN 'prata' THEN 'ampliado' ELSE 'avançado' END,s.delivery_formats,false,'approved',s.version,lv.version,1,true
FROM updates u JOIN public.service_catalog s ON s.code=u.code JOIN public.service_level_catalog lv ON lv.code=u.level
ON CONFLICT(service_code,level_code) DO UPDATE SET budget_description=excluded.budget_description,contract_scope=excluded.contract_scope,annex_scope=excluded.annex_scope,parameters=excluded.parameters,review_status='approved',source_service_version=excluded.source_service_version,source_level_version=excluded.source_level_version,inherit_legacy_catalog=false,version=public.service_level_scope_catalog.version+1,updated_at=now();
INSERT INTO public.service_level_scope_versions(service_code,level_code,version,snapshot,created_by) SELECT service_code,level_code,version,to_jsonb(s),null FROM public.service_level_scope_catalog s WHERE service_code IN ('c','f','g','k','l','m','q','am','an','ao') ON CONFLICT(service_code,level_code,version) DO NOTHING;
INSERT INTO public.document_text_catalog_versions(text_code,version,snapshot,contract_master_version,created_by) SELECT code,version,to_jsonb(t),last_contract_master_version,null FROM public.document_text_catalog t WHERE code IN ('scope_limits_rule','anexo_scope_governance','proposal_client_inputs_rule') ON CONFLICT(text_code,version) DO NOTHING;
UPDATE public.document_text_catalog SET body='Somente os itens expressamente incluídos no orçamento e confirmados no Anexo I integram o serviço contratado. Não se presumem projetos complementares, documentos de terceiros, levantamentos topográficos ou planialtimétricos, execução ou aprovações fora do escopo. Nos processos de legalização, a CONTRATADA providencia apenas os projetos contratados, as ARTs legalmente exigíveis de seus trabalhos e as etapas administrativas expressamente previstas. O CONTRATANTE providencia e custeia os demais documentos e todas as taxas de prefeitura e ART, sem afastar a correção de falhas próprias da CONTRATADA.',version=version+1,last_contract_master_version=5,updated_at=now() WHERE code='scope_limits_rule';
UPDATE public.document_text_catalog SET body='Este Anexo I identifica os serviços contratados, suas entregas, quantidades, revisões, formatos, prazos, preços e limites. A simples referência a um nível não acrescenta outras atividades. Nas contratações de legalização, Alvará e Habite-se, certidões, matrículas, laudos, topografia, planialtimetria e demais documentos externos não se incluem automaticamente e são providenciados e pagos pelo CONTRATANTE. A taxa da ART legalmente exigível é integralmente custeada pelo CONTRATANTE, por adiantamento ou reembolso comprovado quando aplicável.',version=version+1,last_contract_master_version=5,updated_at=now() WHERE code='anexo_scope_governance';
UPDATE public.document_text_catalog SET body='O CONTRATANTE fornecerá os documentos próprios, certidões, matrículas, autorizações, levantamentos e demais insumos necessários ao projeto e à legalização, incluindo documentos topográficos e planialtimétricos quando exigidos e não contratados separadamente. O CONTRATANTE também custeará todas as taxas de ART e prefeitura. A falta de documentos ou pagamento a seu cargo pode suspender a etapa afetada, após comunicação, sem afastar obrigações técnicas da CONTRATADA nem a correção de erros próprios.',version=version+1,last_contract_master_version=5,updated_at=now() WHERE code='proposal_client_inputs_rule';
INSERT INTO public.document_text_catalog_versions(text_code,version,snapshot,contract_master_version,created_by) SELECT code,version,to_jsonb(t),last_contract_master_version,null FROM public.document_text_catalog t WHERE code IN ('scope_limits_rule','anexo_scope_governance','proposal_client_inputs_rule') ON CONFLICT(text_code,version) DO NOTHING;
UPDATE public.service_catalog SET last_contract_master_version=5 WHERE active AND last_contract_master_version IS DISTINCT FROM 5;
UPDATE public.service_level_catalog SET last_contract_master_version=5 WHERE active AND last_contract_master_version IS DISTINCT FROM 5;
UPDATE public.document_text_catalog SET last_contract_master_version=5 WHERE active AND last_contract_master_version IS DISTINCT FROM 5;
UPDATE public.document_rule_reviews SET status='resolved',resolved_at=now(),reason=reason||' | Revisão técnica do novo catálogo e texto mestre v5 com solicitação expressa de publicação em 01/11/2026.' WHERE contract_master_version=5 AND status='pending';
UPDATE public.commercial_records SET contract_master_id=(SELECT id FROM public.contract_master_versions WHERE active=true AND version=5), contract_master_version=5,smart_texts=public.current_document_text_snapshot_all(),updated_at=now() WHERE contract_number='CON-2026-10-0002' AND contract_master_version=4;
INSERT INTO public.audit_log(user_id,action,entity_type,details) VALUES(null,'publish_contract_master_v5_legalization_art','contract_master_versions','{"published_at":"2026-11-01","reason":"explicit user approval","scope":"41 services 123 level combinations, technical/legal updates, frozen historical versions preserved","contract":"CON-2026-10-0002","new_contract_master_version":5}'::jsonb);
DO $verify$ DECLARE v_bad int; BEGIN
IF (SELECT count(*) FROM public.contract_master_versions WHERE active)<>1 OR (SELECT version FROM public.contract_master_versions WHERE active)<>5 THEN RAISE EXCEPTION 'Master inválido';END IF;
IF (SELECT count(*) FROM public.service_catalog WHERE active)<>41 OR (SELECT count(*) FROM public.service_level_scope_catalog WHERE active)<>123 THEN RAISE EXCEPTION 'Catálogo/níveis divergentes';END IF;
IF (SELECT count(*) FROM public.service_level_scope_catalog WHERE active AND review_status<>'approved')>0 THEN RAISE EXCEPTION 'Existem níveis não aprovados';END IF;
IF (SELECT count(*) FROM public.document_rule_reviews WHERE contract_master_version=5 AND status='pending')>0 THEN RAISE EXCEPTION 'Revisões pendentes';END IF;
IF (SELECT count(*) FROM public.service_catalog WHERE active AND last_contract_master_version IS DISTINCT FROM 5)+(SELECT count(*) FROM public.service_level_catalog WHERE active AND last_contract_master_version IS DISTINCT FROM 5)+(SELECT count(*) FROM public.document_text_catalog WHERE active AND last_contract_master_version IS DISTINCT FROM 5)>0 THEN RAISE EXCEPTION 'Catálogo incoerente com mestre';END IF;
IF (SELECT contract_master_version FROM public.commercial_records WHERE contract_number='CON-2026-10-0002')<>5 THEN RAISE EXCEPTION 'Vínculo Tributino não atualizado';END IF;
IF (SELECT count(*) FROM public.documentos WHERE id in ('cbf8ae43-72d6-4670-bcf3-1392e1a3ef0b','c93ffab0-e9b9-43e1-839b-3af1c382aca8') AND versao='1.0')<>2 THEN RAISE EXCEPTION 'Histórico 1.0 alterado';END IF;
END $verify$;
COMMIT;
